"""JARVIS embeddable Python: wire offline gesture pywin32 DLLs.

Embeddable builds ignore PYTHONPATH. pywin32 lives under
resources/gestures/site-packages — we only append those paths AFTER
Lib/site-packages so Silero's own numpy/torch are never shadowed by a
trimmed gestures numpy (which breaks local TTS after packaging).
"""
from __future__ import annotations

import os
import sys
from pathlib import Path


def _wire_gesture_pywin32() -> None:
    try:
        # .../tts/runtime/python/Lib/site-packages/sitecustomize.py -> resources/
        resources = Path(__file__).resolve().parents[5]
    except Exception:
        return
    gest = resources / "gestures" / "site-packages"
    if not gest.is_dir():
        return

    # Append only — never insert(0). Gestures numpy is often stripped of
    # _multiarray_tests and will crash import if it wins over TTS numpy.
    extra = [
        gest,
        gest / "win32",
        gest / "win32" / "lib",
        gest / "Pythonwin",
    ]
    for p in extra:
        s = str(p)
        if p.is_dir() and s not in sys.path:
            sys.path.append(s)

    dll = gest / "pywin32_system32"
    if dll.is_dir():
        dll_s = str(dll)
        path = os.environ.get("PATH", "")
        if dll_s.lower() not in path.lower():
            os.environ["PATH"] = dll_s + os.pathsep + path
        if hasattr(os, "add_dll_directory"):
            try:
                os.add_dll_directory(dll_s)
            except OSError:
                pass

    try:
        import pywin32_bootstrap  # noqa: F401
    except Exception:
        pass


_wire_gesture_pywin32()
